package com.example.rokidkeyboardbridge;
import android.content.Context;import android.graphics.*;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.atomic.*;
public final class WarmPresenceChecks {
 static int n;static void ok(boolean v,String label){n++;if(!v)throw new AssertionError("warm presence "+n+": "+label);}
 static Object getField(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 static void ui(Runnable r)throws Exception{ApprovedQuietPoseChecks.ui(r);}
 public static int run(Context context,Context assets)throws Exception{
  n=0;CharacterChoreography.scene=0;CharacterChoreography.phase=CharacterChoreography.IDLE;CharacterMotionTuning.warmth=2;
  ok(WarmPresencePolicy.command("ロキ")==WarmPresencePolicy.LOOK,"name response");ok(WarmPresencePolicy.command("ロキ、こっちを見て")==WarmPresencePolicy.LOOK,"look alias");ok(WarmPresencePolicy.command("甘えて")==WarmPresencePolicy.NEAR,"gentle proximity");ok(WarmPresencePolicy.command("軽いキス顔にして")==WarmPresencePolicy.KISS_FACE,"light face only");
  for(String text:new String[]{"この写真のロキはかわいい？","彼女にこっちを見てと言った","ロキの名前の意味は？","カレンダーに登録して","手をつなぐ方法を教えて"})ok(WarmPresencePolicy.command(text)==0,"ordinary/quoted request excluded");
  for(String text:new String[]{"少し色っぽくして","色っぽい表情にして","大人っぽく微笑んで"})ok(WarmPresencePolicy.command(text)==WarmPresencePolicy.SHY,"gentle expression aliases");
  for(String text:new String[]{"色っぽい表情の意味を教えて","彼女に隣にいてと言った","色っぽい表情にしないで"})ok(WarmPresencePolicy.command(text)==0,"negation and quoted context excluded");
  WarmPresencePolicy flow=new WarmPresencePolicy();flow.user("隣にいて",1000);flow.user("いいね",2000);ok(flow.active(2500),"short followup retains atmosphere");flow.user("明日の予定を教えて",3000);ok(!flow.active(3100),"ordinary topic clears atmosphere");flow.user("少し色っぽくして",4000);flow.user("そのまま",5000);ok(!flow.active(11000),"followup does not extend indefinitely");
  WarmPresencePolicy p=new WarmPresencePolicy();p.user("こっちを見て",1000);ok(p.active(1500),"event active");ok(p.gaze(2000,0,false)==0,"first make eye contact");ok(p.gaze(3500,0,false)<0,"then glance aside");ok(p.gaze(5200,0,false)>0,"settle with soft gaze");ok(!p.active(8000),"finite event");
  p.user("少し近くに来て",10000);float natural=p.approach(11500,0,false);ok(natural>0&&natural<=.014f,"bounded uniform proximity");ok(p.approach(11500,2,false)<natural,"speech stays subtle");ok(p.approach(11500,0,true)==0,"quiet mode suppresses");p.user("こっちを見て",10100);ok(p.approach(11600,0,false)<natural,"new intent wins immediately");
  p.user("近づかないで",12000);ok(!p.active(12100),"opt-out immediate");p.user("甘えて",13000);CharacterChoreography.scene=1;ok(!p.active(14000),"navigation clears event");CharacterChoreography.scene=0;ok(!p.active(14000),"no stale event after navigation");
  ok(CharacterMotionPreferences.saveWarmth(context,3)&&CharacterMotionTuning.warmth==3,"strength stored");p.user("甘えて",15000);ok(p.approach(16500,0,false)>=natural,"rich strength bounded");ok(CharacterMotionPreferences.saveWarmth(context,0)&&!p.active(16500),"off disables");SettingsJournal.undo(context);ok(CharacterMotionTuning.warmth==3,"undo strength");CharacterMotionPreferences.saveWarmth(context,2);
  VirtualContactPolicy contact=new VirtualContactPolicy();contact.user("手をつないで",1000);contact.answer("手をつないで","そっと手をつなぎますね。",1100);ok(contact.frame(1200).kind==VirtualContactPolicy.HAND,"explicit hand request accepted");contact.user("こっちを見て",3000);ok(contact.frame(10000).kind==VirtualContactPolicy.HAND,"hand preserved across gaze and event end");contact.user("手を離して",11000);ok(contact.frame(11100).kind==VirtualContactPolicy.NONE,"hand release");
  AtomicReference<PortraitExpressionRenderer> ref=new AtomicReference<>();ui(()->ref.set(new PortraitExpressionRenderer(assets)));PortraitExpressionRenderer portrait=ref.get();Bitmap bitmap=Bitmap.createBitmap(512,768,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);AtomicBoolean drawn=new AtomicBoolean();ui(()->{portrait.warmUser("少し近くに来て",30000);drawn.set(portrait.draw(canvas,512,768,0,0,false,false,32700));});ok(drawn.get(),"portrait gentle reaction draws");Field cell=PortraitExpressionRenderer.class.getDeclaredField("previous");cell.setAccessible(true);ok(cell.getInt(portrait)==7,"soft smile original cell");try(FileOutputStream out=new FileOutputStream(new File(context.getFilesDir(),"warm-presence-preview.png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}ui(portrait::release);bitmap.recycle();
  AtomicReference<ApprovedFaceRenderer> faceRef=new AtomicReference<>();ui(()->{ApprovedFaceRenderer face=new ApprovedFaceRenderer(assets);face.warmCommand("軽いキス顔にして",40000);faceRef.set(face);});Field kisses=ApprovedFaceRenderer.class.getDeclaredField("kisses");kisses.setAccessible(true);Object renderer=kisses.get(faceRef.get());Field type=KissPortraitRenderer.class.getDeclaredField("preview");type.setAccessible(true);ok(type.getInt(renderer)==0,"only light kiss variant selected");ui(()->faceRef.get().warmCommand("親密な演出を止めて",40100));ok(type.getInt(renderer)==-1,"light preview stopped");ui(()->faceRef.get().warmCommand("少し近くに来て",50000));ok(faceRef.get().needsFastFrames(51000),"warm gaze requests smooth frames");ui(()->faceRef.get().rapportUser("明日の予定を教えて",52000));ok(!((PortraitExpressionRenderer)getField(faceRef.get(),"expressions")).warmMoving(52100),"ordinary topic clears face warmth");ui(()->faceRef.get().warmCommand("軽いキス顔にして",60000));ui(()->faceRef.get().rapportUser("いいね",61000));ok(type.getInt(renderer)==0,"followup preserves light face");ui(()->faceRef.get().rapportUser("明日の予定を教えて",62000));ok(type.getInt(renderer)==-1,"topic change clears light face");ui(()->faceRef.get().release());return n;
 }
}
